    const backLeftFoot = new THREE.Vector3(-supportStanceWidth / 2, supportBaseHeight, -supportBaseDepth / 2);
    const backRightFoot = new THREE.Vector3(supportStanceWidth / 2, supportBaseHeight, -supportBaseDepth / 2);
